     3	import com.loja.domain.PaymentMethod;
     4	import com.loja.util.MoneyUtils;
     5	
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	
     9	public class PaymentAdjustmentCalculator {
    10	    public BigDecimal calculate(BigDecimal orderTotal, PaymentMethod paymentMethod, int installments, boolean hasCoupon) {
    11	        return switch (paymentMethod) {
    12	            case PIX -> {
    13	                if (hasCoupon) {
    14	                    yield MoneyUtils.roundMoney(BigDecimal.ZERO);
    15	                }
    16	                BigDecimal discount = MoneyUtils.roundMoney(orderTotal.multiply(new BigDecimal("0.05")));
    17	                yield discount.negate();
    18	            }
    19	            case BANK_SLIP -> new BigDecimal("3.49");
    20	            case CREDIT_CARD -> {
    21	                if (installments <= 3) {
    22	                    yield MoneyUtils.roundMoney(BigDecimal.ZERO);
    23	                }
    24	                BigDecimal rate = new BigDecimal("0.0199");
    25	                BigDecimal onePlusRate = BigDecimal.ONE.add(rate);
    26	                BigDecimal denominator = BigDecimal.ONE.subtract(
    27	                    onePlusRate.pow(-installments)
    28	                );
    29	                BigDecimal installmentAmount = orderTotal.multiply(rate).divide(denominator, 10, RoundingMode.HALF_EVEN);
    30	                installmentAmount = MoneyUtils.roundMoney(installmentAmount);
    31	                BigDecimal finalTotal = installmentAmount.multiply(new BigDecimal(installments));
    32	                yield MoneyUtils.roundMoney(finalTotal.subtract(orderTotal));
    33	            }
    34	        };
    35	    }
    36	
    37	    public BigDecimal calculateInstallmentAmount(BigDecimal finalTotal, int installments) {
    38	        return MoneyUtils.roundMoney(finalTotal.divide(new BigDecimal(installments), 10, RoundingMode.HALF_EVEN));
    39	    }
    40	}
