     9	import java.math.BigDecimal;
    10	import java.net.URI;
    11	import java.net.http.HttpClient;
    12	import java.net.http.HttpRequest;
    13	import java.net.http.HttpResponse;
    14	import java.time.Duration;
    15	
    16	public class TransLogClient {
    17	    private final String transLogUrl;
    18	    private final HttpClient httpClient;
    19	    private final ObjectMapper objectMapper;
    20	
    21	    public TransLogClient(String transLogUrl) {
    22	        this.transLogUrl = transLogUrl;
    23	        this.httpClient = HttpClient.newBuilder()
    24	            .connectTimeout(Duration.ofSeconds(2))
    25	            .build();
    26	        this.objectMapper = new ObjectMapper();
    27	    }
    28	
    29	    public ShippingResult quote(String zipCode, BigDecimal weightKg, ShippingMethod method, Region region) {
    30	        String service = method == ShippingMethod.ECONOMY ? "STD" : "EXP";
    31	        int weightGrams = weightKg.multiply(new BigDecimal("1000")).intValue();
    32	
    33	        String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
    34	            transLogUrl, zipCode, weightGrams, service);
    35	
    36	        try {
    37	            HttpRequest request = HttpRequest.newBuilder()
    38	                .uri(URI.create(url))
    39	                .timeout(Duration.ofSeconds(2))
    40	                .GET()
    41	                .build();
    42	
    43	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
    44	
    45	            if (response.statusCode() == 200) {
    46	                JsonNode json = objectMapper.readTree(response.body());
    47	
    48	                if (json.has("error")) {
    49	                    return null;
    50	                }
    51	
    52	                int priceCents = json.get("price_cents").asInt();
    53	                int etaHours = json.get("eta_hours").asInt();
    54	
    55	                BigDecimal price = MoneyUtils.roundMoney(new BigDecimal(priceCents).divide(new BigDecimal("100")));
    56	                int deliveryDays = (int) Math.ceil(etaHours / 24.0);
    57	
    58	                int additionalDays = switch (region) {
    59	                    case NORTH -> 3;
    60	                    case NORTHEAST -> 2;
    61	                    default -> 0;
    62	                };
    63	
    64	                return new ShippingResult(price, deliveryDays + additionalDays);
    65	            }
    66	        } catch (Exception e) {
    67	        }
    68	
    69	        throw new RuntimeException("CARRIER_UNAVAILABLE");
    70	    }
    71	}

