  1	package com.loja.service;
  2	
  3	import com.loja.domain.*;
  4	import com.loja.repository.OrderRepository;
  5	import com.loja.repository.ProductRepository;
  6	import com.loja.service.club.ClubBenefitsCalculator;
  7	import com.loja.service.coupon.CouponService;
  8	import com.loja.service.coupon.CouponStrategy;
  9	import com.loja.service.insurance.InsuranceCalculator;
 10	import com.loja.service.payment.PaymentAdjustmentCalculator;
 11	import com.loja.service.shipping.ShippingCalculator;
 12	import com.loja.service.shipping.ShippingResult;
 13	import com.loja.util.ApiException;
 14	import com.loja.util.MoneyUtils;
 15	
 16	import java.math.BigDecimal;
